.dev-gamemonetize {
	margin-top: 97px;
	margin-bottom: 140px;
}

.benefit-card {
	text-align: center;
}

.benefit-card a.button {
	position: relative;
	line-height: 1;
	text-align: center;
	text-decoration: none;
	width: 206px;
}

.benefit-card .section__control {
	padding-top: 19px;
	text-align: center;
}

.benefit-card .section__control.last {
	padding-bottom: 20px;
}

.dev-benefits {
	margin-bottom: 120px;
}

.dev-gamemonetize__bg {
	background-image: none;
}

.dev-platform__item:not(:last-child) {
	position: relative;
	padding: 20px 20px 20px 50px;
	border-radius: 5px;
}

.section__header {
	margin-bottom: 17px;
}

.dev-platform {
	margin-bottom: 100px;
}

.main-games__title {
	position: relative;
	font-size: 40px;
	padding-bottom: 5px;
}

.section {
	margin-bottom: 120px;
